def svg(path, w, h, icons, label, c1, c2, stroke, ink):
    n=len(icons); size=min(h*0.42, w*0.8/n)
    gap=size*0.25; total=n*size+(n-1)*gap; x0=(w-total)/2; y0=h*0.45-size/2
    g=''.join(f'<g transform="translate({x0+i*(size+gap):.1f} {y0:.1f}) scale({size/100:.3f})">{ICONS[k]}</g>' for i,k in enumerate(icons))
    fs=max(22, int(w/38))
    s=f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">
<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{c1}"/><stop offset="1" stop-color="{c2}"/></linearGradient></defs>
<rect width="{w}" height="{h}" fill="url(#g)"/>
<g fill="none" stroke="{stroke}" stroke-width="{max(2.2, 3.2*100/size):.2f}" stroke-linecap="round" stroke-linejoin="round" opacity=".9">{g}</g>
<text x="{w/2}" y="{h*0.45+size/2+fs*2.2:.0f}" text-anchor="middle" font-family="'Hiragino Sans','Noto Sans CJK JP',sans-serif" font-size="{fs}" letter-spacing="3" fill="{ink}">{label}</text>
</svg>'''
    import os; os.makedirs(os.path.dirname(path), exist_ok=True)
    open(path,'w',encoding='utf-8').write(s)
